record.field:
for sol in records:
    sol.write({
        'qty_delivered': sol.qty_delivered + sol.quantity_increment,
        'quantity_increment': 0,
        'progress_increment': 0,
    })
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'message': "Delivered quantities updated.",
        'type': 'success',
        'next': {'type': 'ir.actions.client', 'tag': 'soft_reload'},
    },
}

for bom in records:
    # Archive any existing template for the same product
    old_templates = env['mrp.bom'].search([
        ('product_id', '=', bom.product_id.id),
        ('is_template', '=', True),
        ('id', '!=', bom.id),
    ])
    old_templates.write({'active': False})
    bom.write({'is_template': True})
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'message': ', '.join(b.code for b in records) + " saved as template.",
        'type': 'success',
    },
}

for bom in records:
            bom.write({'unit_price': sum(
        line.unit_price * line.product_qty
        for line in bom.bom_line_ids
            )})

project_id = env.context.get('project_id')
active_ids = env.context.get('active_ids', [])

if project_id:
    so_ids = env['sale.order'].search([('project_id', '=', project_id)]).ids
elif active_ids:
    so_ids = active_ids
else:
    so_ids = []

domain = [('so_id', 'in', so_ids)] if so_ids else []

action = {
    'name': "Cost Nature Analysis",
    'type': 'ir.actions.act_window',
    'res_model': 'construction.cost.nature.analysis.report',
    'view_mode': 'list',
    'domain': domain,
    'context': {
        'search_default_group_by_cost_nature': True,
        'search_default_group_by_category': True,
        'search_default_group_by_product': True,
    },
}
